const downloadSLRReport = () => {
  if (!slrData || !slrData.data) return;

  const poVendorMap = new Map();
  if (sap && sap.purchaseOrders) {
    sap.purchaseOrders.forEach((po: any) => {
      poVendorMap.set(po.poNumber, po.vendorName || 'Unknown Vendor');
    });
  }

  const rows = [];
  rows.push(['--- SLR Purchase Orders Breakdown ---']);
  rows.push(['PO Number', 'Vendor Name', 'Type', 'Description', 'Total Amount', 'Actual', 'Commitment', 'Status']);

  const slrFiltered = slrData.data.filter((r: any) => (slrTypeFilter === 'ALL' || r.type === slrTypeFilter) && (slrStatusFilter === 'ALL' || r.status === slrStatusFilter));

  slrFiltered.forEach((row: any) => {
    const vendorName = poVendorMap.get(row.po_document) || 'Unknown Vendor';

    rows.push([
      row.po_document || '',
      `"${vendorName.replace(/"/g, '""')}"`,
      row.type || '',
      `"${(row.description || '').replace(/"/g, '""')}"`,
      row.total || 0,
      row.actual || 0,
      row.commitment || 0,
      row.status || ''
    ]);

    if (row.line_items?.length > 0) {
      row.line_items.forEach((item: any, j: number) => {
        rows.push([
          `  Line ${j + 1}`,
          `"${vendorName.replace(/"/g, '""')}"`,
          item.type || '',
          `"${(item.description || '').replace(/"/g, '""')}"`,
          item.total || 0,
          item.actual || 0,
          item.commitment || 0,
          ''
        ]);
      });
    }
  });

  const csvContent = "data:text/csv;charset=utf-8," + rows.map(e => e.join(",")).join("\n");
  const encodedUri = encodeURI(csvContent);
  const link = document.createElement("a");
  link.setAttribute("href", encodedUri);
  link.setAttribute("download", `SLR_Breakdown_${p.projectId}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

